export function SocialIcon({ name, className = "w-5 h-5" }) {
  if (name === "whatsapp") {
    return (
      <img
        src={assetPath("/images/whatsapp-channels.png")}
        alt=""
        className={`${className} object-contain rounded-sm transition-all duration-300 opacity-55 grayscale brightness-110 contrast-90 group-hover:opacity-100 group-hover:grayscale-0 group-hover:brightness-100 group-hover:contrast-100`}
        aria-hidden="true"
      />
    );
  }

  const icon = icons[name];
  if (!icon) return null;
  return (
    <svg className={className} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      {icon}
    </svg>
  );
}

export function SocialLink({ item, size = "md" }) {
  const sizeClasses =
    size === "lg"
      ? "w-11 h-11"
      : size === "sm"
        ? "w-9 h-9"
        : "w-10 h-10";

  const isWhatsAppChannel = item.id === "whatsapp";

  return (
    <a
      href={item.href}
      target="_blank"
      rel="noopener noreferrer"
      title={item.label}
      aria-label={item.label}
      className={`${sizeClasses} group flex items-center justify-center rounded-lg border border-white/10 bg-white/[0.03] text-white/55 transition-all duration-300 hover:scale-105 hover:shadow-lg hover:border-white/20 hover:text-white`}
      onMouseEnter={(e) => {
        e.currentTarget.style.color = item.color;
        e.currentTarget.style.borderColor = `${item.color}66`;
        e.currentTarget.style.boxShadow = `0 8px 24px ${item.color}33`;
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.color = "";
        e.currentTarget.style.borderColor = "";
        e.currentTarget.style.boxShadow = "";
      }}
    >
      <SocialIcon
        name={item.id}
        className={isWhatsAppChannel ? "w-[62%] h-[62%]" : "w-[52%] h-[52%]"}
      />
    </a>
  );
}

export function SocialLinksRow({ links, size = "md", className = "" }) {
  return (
    <div className={`flex flex-wrap items-center gap-3 ${className}`}>
      {links.map((item) => (
        <SocialLink key={item.id} item={item} size={size} />
      ))}
    </div>
  );
}
